func add(a: int, b: int) -> int {
    return a + b;
}

let result := add(3, 7);
println(result);

func greet(name: string) {
    println("Hello, " + name + "!");
}

greet("Alice");
greet("Bob");

func factorial(n: int) -> int {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

let result := factorial(5);
println(result);

func is_even(n: int) -> bool {
    return n % 2 == 0;
}

let result := is_even(4);
println(result);

func average(a: real, b: real) -> real {
    return (a + b) / 2.0;
}

let avg := average(10.0, 20.0);
println(avg);

func double(n: int) -> int {
    return n * 2;
}

func square(n: int) -> int {
    return n * n;
}

let x := 5;
println(double(x));
println(square(x));
